def restore_ip_addresses(s):
    n = len(s)
    result = []
    path = []

    def is_valid(segment):
        if len(segment) > 1 and segment[0] == '0':
            return False
        return 0 <= int(segment) <= 255

    def backtrack(start):
        if len(path) == 4:
            if start == n:
                result.append('.'.join(path))
            return
        for length in range(1, 4):
            if start + length > n:
                break
            segment = s[start:start + length]
            if is_valid(segment):
                path.append(segment)
                backtrack(start + length)
                path.pop()

    backtrack(0)
    result.sort()
    return result

